import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CZqXuAiL.js";const m=JSON.parse('{"title":"VPS & Dedicated Server Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/getting-started/vps-deployment.md","filePath":"openshield-xdp/getting-started/vps-deployment.md","lastUpdated":null}'),r={name:"openshield-xdp/getting-started/vps-deployment.md"};function n(d,e,i,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="vps-dedicated-server-deployment" tabindex="-1">VPS &amp; Dedicated Server Deployment <a class="header-anchor" href="#vps-dedicated-server-deployment" aria-label="Permalink to &quot;VPS &amp; Dedicated Server Deployment&quot;">​</a></h1><p>How OpenShield-XDP behaves across the three real-world topologies: installed inside a VPS, on the dedicated host with routed IPs, and on a NAT&#39;d host.</p><h2 id="the-one-thing-to-understand-first" tabindex="-1">The one thing to understand first <a class="header-anchor" href="#the-one-thing-to-understand-first" aria-label="Permalink to &quot;The one thing to understand first&quot;">​</a></h2><p>XDP attaches to a <strong>network interface</strong> and sees exactly the packets that arrive on that interface&#39;s wire — nothing more, nothing less. Every packet self-describes its destination IP and destination port (we parse the L3/L4 headers directly), so &quot;which VPS is this for&quot; and &quot;which port is this for&quot; are read from the packet, never guessed.</p><h2 id="model-1-—-openshield-inside-each-vps-recommended-for-tenant-vpses" tabindex="-1">Model 1 — OpenShield inside each VPS (recommended for tenant VPSes) <a class="header-anchor" href="#model-1-—-openshield-inside-each-vps-recommended-for-tenant-vpses" aria-label="Permalink to &quot;Model 1 — OpenShield inside each VPS (recommended for tenant VPSes)&quot;">​</a></h2><p>Each VPS installs OpenShield on its own <code>eth0</code>.</p><ul><li>The VPS&#39;s XDP sees <strong>only that VPS&#39;s traffic</strong> — perfect per-tenant isolation. Customer A&#39;s flood never affects customer B&#39;s rules.</li><li>Each tenant gets their own config, thresholds, presets, license.</li><li>Works with KVM/QEMU, VMware, Xen, Hyper-V — the guest NIC just needs XDP (virtio works; we fall back to generic mode automatically).</li></ul><h2 id="model-2-—-openshield-on-the-dedicated-host-bridged-routed-vms" tabindex="-1">Model 2 — OpenShield on the dedicated host (bridged/routed VMs) <a class="header-anchor" href="#model-2-—-openshield-on-the-dedicated-host-bridged-routed-vms" aria-label="Permalink to &quot;Model 2 — OpenShield on the dedicated host (bridged/routed VMs)&quot;">​</a></h2><p>The host&#39;s physical NIC carries <strong>all</strong> VMs&#39; traffic mixed together. Each VPS has its own public IP, and that is the separation key:</p><ul><li><strong>Per-IP separation is automatic.</strong> Scoring, bans, thresholds and the attack cap are all per <em>source</em> IP, and flows are distinguished by destination IP. Two VMs both running Minecraft on port 25565 do <strong>not</strong> overlap — they are different destination IPs. Port numbers are parsed per packet, but protection state is keyed by IP, so shared ports across VMs never collide.</li><li>A flood aimed at VPS-A gets mitigated at the host level — before it ever reaches the VM. That <em>is</em> the protection working; a ban on the attack source only blocks traffic to the targeted VM&#39;s IP.</li><li>The host&#39;s own services share the same wire. Whitelist your own admin IPs and consider whether the host OS itself should be protected or left mostly-pass-through.</li><li>Set <code>dynamic.attack_min_pps</code> for the <strong>aggregate</strong> wire rate of all VMs combined, not for one VM.</li></ul><h2 id="model-3-—-dedicated-host-with-nat-port-forwarding-avoid" tabindex="-1">Model 3 — Dedicated host with NAT port-forwarding (avoid) <a class="header-anchor" href="#model-3-—-dedicated-host-with-nat-port-forwarding-avoid" aria-label="Permalink to &quot;Model 3 — Dedicated host with NAT port-forwarding (avoid)&quot;">​</a></h2><p>With DNAT, inbound packets arrive at the NIC with the <strong>host&#39;s public IP</strong> as the destination — XDP runs <em>before</em> conntrack/NAT, so it cannot see which VM the packet will eventually be forwarded to.</p><ul><li>Per-VM separation is <strong>impossible at XDP level</strong> here — every packet shows the host IP as destination.</li><li>Port-forwarded services also collide by design (80 → VM-A:8080, 81 → VM-B:80 looks like two ports on one IP).</li><li><strong>Recommendation:</strong> don&#39;t protect NAT&#39;d tenants from the host. Install OpenShield <strong>inside each VPS</strong> (Model 1), or give the VMs routed/bridged public IPs (Model 2).</li></ul><h2 id="what-xdp-can-never-see" tabindex="-1">What XDP can never see <a class="header-anchor" href="#what-xdp-can-never-see" aria-label="Permalink to &quot;What XDP can never see&quot;">​</a></h2><p>Traffic <strong>between VMs on the same host</strong> (VM-A ↔ VM-B over the internal bridge) never touches the physical NIC, so host-level XDP never sees it. Only the VPSes themselves see that traffic — another reason Model 1 is the most complete option for multi-tenant hosts.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where installed</th><th>Sees</th><th>Per-VPS separation</th><th>Recommended</th></tr></thead><tbody><tr><td>Inside each VPS</td><td>That VPS only</td><td>Perfect</td><td>✅ Best for tenant VPSes</td></tr><tr><td>Host, routed/bridged VMs</td><td>All VMs + host</td><td>Automatic via per-IP</td><td>✅ Good for your own fleet</td></tr><tr><td>Host, NAT port-forward</td><td>Host IP only</td><td>None</td><td>❌ Install inside VPSes</td></tr></tbody></table>',17)])])}const f=t(r,[["render",n]]);export{m as __pageData,f as default};
